    private String recompense;
    private String type;
    private int classement;
    private String description;
    private int tournamentId;
    private java.time.LocalDateTime dateCreation;
    private java.time.LocalDateTime dateModification;
    private String statutRecompense;
    private int coutEstimation;

    public Recompense() {
    }

    public Recompense(String recompense, String type, int classement, String description, int tournamentId) {
        this.recompense = recompense;
        this.type = type;
        this.classement = classement;
        this.description = description;
        this.tournamentId = tournamentId;
    }

    public int getId() {
        return id;
    }

    public void setId(int id) {
        this.id = id;
    }

    public String getRecompense() {
        return recompense;
    }

