    }

    @Override
    public String toString() {
        return "Recompense{" +
                "id=" + id +
                ", recompense='" + recompense + '\'' +
                ", type='" + type + '\'' +
                ", classement=" + classement +
                ", description='" + description + '\'' +
                ", tournamentId=" + tournamentId +
                '}';
    }
}
